 def __init__(self,store): self.store=store; self.settled={}
 def reserve(self,request):
  if request.request_id in self.settled: return True
  taken=[]
  try:
   for shard,amount in request.amounts.items():
    self.store.take(shard,amount); taken.append((shard,amount))
  except Exception:
   for shard,amount in reversed(taken): self.store.give_back(shard,amount)
   raise
  self.settled[request.request_id]=True
  return True

